from pathlib import Path
R=Path(__file__).resolve().parents[1]
old=(R/'output/pre-final-journey-flow/src/booking/main.tsx').read_text(encoding='utf-8')
art=old[old.index('function VehicleArt('):old.index('function App(){')]
source='''import {useState,useEffect,useRef,useId} from 'react';
import {createRoot} from 'react-dom/client';
import {createPortal} from 'react-dom';
import {MotionConfig,motion} from 'framer-motion';
import {ArrowRight,ArrowLeft,Check,CarFront,MessageCircle,X} from 'lucide-react';
import {useDecorativeMotion} from '@/components/ui/parallax-scroll-feature-section';
import {useMomentumRail} from '@/components/ui/use-momentum-rail';
import SlideCommit from '@/components/ui/SlideCommit';
import {SERVICES,PACKAGES,DAY_PACKAGES,FLEET,type VehicleId,type TravelPackage} from './data';

const KEY='heavenly-journey-selection-v3';
type Customer={name:string;people:string;date:string;pickup:string};
type Selection={service:string;packageId:string;vehicle:VehicleId|null;preference:string;customer:Customer};
function load():Selection {let saved:Partial<Selection>={};try{saved=JSON.parse(sessionStorage.getItem(KEY)||'{}')}catch{}let legacy=window.HeavenlyTrip?.get();if(!legacy){try{const old=JSON.parse(sessionStorage.getItem('heavenly-v3-trip')||'{}');legacy={...old,...old.fields,service:old.fields?.['service-request']}}catch{}}
 const query=new URLSearchParams(location.search).get('package');
 return {service:SERVICES.includes(saved.service as typeof SERVICES[number])?saved.service!:legacy?.service||SERVICES[0],packageId:query&&PACKAGES.some(p=>p.id===query)?query:saved.packageId||'',vehicle:!query&&FLEET.some(v=>v.id===saved.vehicle)?saved.vehicle!:null,preference:['Budget friendly package','Deluxe package','Luxury packages','Premium packages'].includes(saved.preference||'')?saved.preference!:'',customer:saved.customer||{name:legacy?.name||'',people:legacy?.people||'4',date:legacy?.date||'',pickup:legacy?.pickup||''}};
}
function persist(s:Selection){try{sessionStorage.setItem(KEY,JSON.stringify(s))}catch{}}
function jump(id:string){document.getElementById(id)?.scrollIntoView({behavior:'instant'})}
function PackagePlan({item}:{item:TravelPackage}){return <>{item.places.length>0&&<ul>{item.places.map(p=><li key={p}>{p}</li>)}</ul>}{item.days.map(d=><div className="day-plan" key={d.title}><h4>{d.title}</h4><ul>{d.places.map(p=><li key={p}>{p}</li>)}</ul></div>)}</>}
function ServicePicker({service,onChange,inside=false}:{service:string;onChange:(value:string)=>void;inside?:boolean}){const id=useId();const temple=['Temple tour','Group package','Custom multi-day South India tour'].includes(service);return <div className={'service-choice '+(inside?'service-choice-inside':'service-choice-below')} data-service-location={inside?'inside':'below'}><div><span className="flow-step-label">PERSONAL TRAVEL ASSISTANCE</span><label htmlFor={id}>What can we arrange for you?</label></div><div className="service-choice-controls"><select id={id} value={service} onChange={e=>onChange(e.target.value)}>{SERVICES.map(s=><option key={s}>{s}</option>)}</select><button className="flow-button" type="button" onClick={()=>temple?jump('journeys'):document.querySelector<HTMLButtonElement>('.site-header [data-contact]')?.click()}>{temple?'Explore the packages':'Discuss this service'} <ArrowRight size={16}/></button></div></div>}
function DayRail(){const scroller=useRef<HTMLDivElement>(null),track=useRef<HTMLUListElement>(null),[index,setIndex]=useState(0);const {goTo}=useMomentumRail(scroller,track,setIndex);const active=DAY_PACKAGES[index]||DAY_PACKAGES[0];return <section id="day-packages" className="day-packages" aria-labelledby="day-packages-title"><header className="flow-section-heading flow-container"><div><p className="flow-eyebrow">STAY A DAY. STAY A LITTLE LONGER.</p><h2 id="day-packages-title">Your time.<br/><em>Your temple journey.</em></h2></div><div><p>Choose from one to five days. Swipe through the journeys, then explore the full plan below.</p><div className="fleet-arrows"><button type="button" aria-label="Previous day package" aria-disabled={index===0} onClick={()=>goTo(index-1)}><ArrowLeft size={18}/></button><button type="button" aria-label="Next day package" aria-disabled={index===DAY_PACKAGES.length-1} onClick={()=>goTo(index+1)}><ArrowRight size={18}/></button><span>{index+1} / 5 · SWIPE TO EXPLORE</span></div></div></header><div ref={scroller} className="momentum-rail" tabIndex={0} role="region" aria-label="One to five day travel packages. Use arrow keys to browse."><ul ref={track} className="momentum-track">{DAY_PACKAGES.map((item,i)=><li key={item.id} className="momentum-card" data-current={index===i}><div className="momentum-card-tilt"><img src={item.image} alt="" loading="lazy" width="700" height="850" draggable={false}/><div className="momentum-card-shade"/><span className="momentum-duration">0{item.duration} {item.duration===1?'DAY':'DAYS'}</span><div className="momentum-card-copy"><span>TEMPLE JOURNEY · 0{i+1}</span><h3><button data-rail-link type="button" aria-pressed={index===i} onClick={()=>goTo(i)}>{item.name}</button></h3><p>{item.note}</p><span className="momentum-card-hint">View itinerary below ↓</span></div></div></li>)}</ul></div><div className="day-rail-dots" aria-label="Choose a duration">{DAY_PACKAGES.map((p,i)=><button type="button" key={p.id} aria-label={`Show ${p.name}`} aria-pressed={index===i} onClick={()=>goTo(i)}><span/>{i+1}</button>)}</div><article className="day-itinerary flow-container" aria-labelledby="active-day-title"><div className="day-itinerary-intro"><p className="flow-eyebrow">YOUR {active.duration}-DAY ITINERARY</p><h3 id="active-day-title">{active.name}</h3><p>{active.note}</p><a className="flow-button" data-day-select={active.id} href={'vehicles.html?package='+active.id}>Select this package <ArrowRight size={17}/></a><p className="day-availability">Darshan is subject to official ticket availability. Travel order and stay arrangements are confirmed with our team.</p></div><div className="day-itinerary-stops" key={active.id}><PackagePlan item={active}/>{active.id==='days-2'&&<p className="flow-qualification">The order across the two days is arranged around your darshan slot and travel needs.</p>}</div></article></section>}
'''+art+'''
function App(){const vehiclePage=location.pathname.replace(/\\/$/,'').endsWith('/vehicles.html')||location.pathname.endsWith('/vehicles');const [state,setState]=useState(load),[review,setReview]=useState(false),[notice,setNotice]=useState(''),[canBack,setCanBack]=useState(false),[canNext,setCanNext]=useState(true);const rail=useRef<HTMLDivElement>(null),dialog=useRef<HTMLDialogElement>(null),form=useRef<HTMLFormElement>(null),returnFocus=useRef<HTMLElement|null>(null),allowed=useDecorativeMotion();const selected=PACKAGES.find(p=>p.id===state.packageId),vehicle=FLEET.find(v=>v.id===state.vehicle),group=state.service==='Group package';const today=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
 useEffect(()=>persist(state),[state]);
 useEffect(()=>{const handler=(e:Event)=>{const service=(e as CustomEvent<string>).detail;if(SERVICES.includes(service as typeof SERVICES[number]))setState(s=>({...s,service}))};window.addEventListener('heavenly:service',handler);return()=>window.removeEventListener('heavenly:service',handler)},[]);
 useEffect(()=>{const saveBeforeNavigation=(e:MouseEvent)=>{const a=(e.target as Element).closest<HTMLAnchorElement>('a[href*="vehicles.html"]');if(!a)return;const snapshot=window.HeavenlyTrip?.get();persist({...state,service:['Temple tour','Group package','Custom multi-day South India tour'].includes(state.service)?state.service:'Temple tour',customer:snapshot?{name:snapshot.name,people:snapshot.people,date:snapshot.date,pickup:snapshot.pickup}:state.customer})};document.addEventListener('click',saveBeforeNavigation,true);return()=>document.removeEventListener('click',saveBeforeNavigation,true)},[state]);
 useEffect(()=>{if(group&&Number(state.customer.people)<3)setState(s=>({...s,customer:{...s.customer,people:'3'}}))},[group]);
 useEffect(()=>{const el=dialog.current;if(review&&el&&!el.open){returnFocus.current=document.activeElement as HTMLElement;el.showModal();document.body.classList.add('modal-open')}else if(!review&&el?.open)el.close()},[review]);
 useEffect(()=>{document.body.classList.toggle('has-booking-selection',vehiclePage&&!!selected&&!!vehicle);return()=>document.body.classList.remove('has-booking-selection')},[vehiclePage,selected,vehicle]);
 const closeReview=()=>{setReview(false);document.body.classList.remove('modal-open');returnFocus.current?.focus({preventScroll:true})};
 const changeService=(service:string)=>{setState(s=>({...s,service}));window.HeavenlyTrip?.setService(service)};
 function measure(){const el=rail.current;if(el){setCanBack(el.scrollLeft>3);setCanNext(el.scrollLeft+el.clientWidth<el.scrollWidth-3)}}
 useEffect(()=>{const el=rail.current;if(!el)return;const observer=new ResizeObserver(measure);observer.observe(el);measure();return()=>observer.disconnect()},[vehiclePage,selected]);
 const slide=(direction:number)=>rail.current?.scrollBy({left:direction*(rail.current.clientWidth*.78),behavior:allowed?'smooth':'instant'});
 function chooseVehicle(id:VehicleId){if(!selected)return;setState(s=>({...s,vehicle:id}));setReview(true);setNotice('Vehicle selected. Review your trip and open the WhatsApp draft.')}
 function openDraft(){if(!selected||!vehicle||!form.current?.reportValidity())return false;const c=state.customer;const lines=['Hello Heavenly Tours & Travels, I would like to book the following trip.',c.name.trim()?`Name: ${c.name.trim()}`:'',`Service: ${state.service}`,`Selected package: ${selected.name}`,state.preference?`Travel preference: ${state.preference}`:'',`Selected vehicle: ${vehicle.name}`,`Travellers: ${c.people}`,`Travel date: ${c.date||'To be discussed'}`,c.pickup.trim()?`Pickup: ${c.pickup.trim()}`:'',selected.note,'ITINERARY',...selected.places,...selected.days.flatMap(d=>[d.title,...d.places]),'Please confirm the travel arrangements, hotel coordination, vehicle model, seating and availability. Darshan assistance is subject to official availability.'];const a=document.createElement('a');a.href='https://wa.me/919700181493?text='+encodeURIComponent(lines.filter(Boolean).join('\\n'));a.target='_blank';a.rel='noopener noreferrer';document.body.append(a);a.click();a.remove();setNotice('WhatsApp draft opened. Review and send it in WhatsApp.');return true}
 const inside=document.getElementById('gateway-service-picker'),below=document.getElementById('below-gateway-service-picker');
 if(!vehiclePage)return <MotionConfig reducedMotion="user"><div className="booking-flow">{inside&&createPortal(<ServicePicker inside service={state.service} onChange={changeService}/>,inside)}{below&&createPortal(<ServicePicker service={state.service} onChange={changeService}/>,below)}<DayRail/></div></MotionConfig>;
 if(!selected)return <div className="booking-flow flow-container vehicle-empty"><p className="flow-eyebrow">YOUR PILGRIMAGE STARTS WITH A PACKAGE</p><h1>Choose your journey first.</h1><p>Explore the seven-place pilgrimage, our five individual tours, or a one-to-five-day package. Then choose your vehicle here.</p><a className="flow-button" href="index.html#pilgrimage">Choose a package <ArrowRight size={18}/></a></div>;
 return <MotionConfig reducedMotion="user"><div className="booking-flow"><section className="selected-journey flow-container"><nav aria-label="Booking steps"><a href="index.html#pilgrimage">01 Package ✓</a><span aria-current="step">02 Vehicle</span><span>03 WhatsApp</span></nav><div className="selected-journey-content"><div><p className="flow-eyebrow">YOUR SELECTED JOURNEY</p><h1>{selected.name}</h1><p>{selected.note}</p><a href="index.html#pilgrimage" className="flow-text-button">Change package <ArrowLeft size={15}/></a></div><details className="selected-itinerary"><summary>View your itinerary</summary><PackagePlan item={selected}/></details></div></section>
 <section id="vehicle-selection" className="flow-fleet" aria-labelledby="fleet-title"><header className="flow-section-heading flow-container"><div><p className="flow-eyebrow">02 · CHOOSE YOUR VEHICLE</p><h2 id="fleet-title">Together,<br/><em>in comfort.</em></h2></div><div><p>Choose a vehicle for your family or group. We’ll confirm the model, seats, luggage space and availability.</p><div className="fleet-arrows"><button type="button" onClick={()=>slide(-1)} disabled={!canBack} aria-label="Previous vehicle"><ArrowLeft size={19}/></button><button type="button" onClick={()=>slide(1)} disabled={!canNext} aria-label="Next vehicle"><ArrowRight size={19}/></button><span>SWIPE OR USE THE ARROWS</span></div></div></header><div ref={rail} className="floating-vehicle-rail" onScroll={measure} aria-label="Five vehicle options">{FLEET.map((item,i)=><motion.button key={item.id} type="button" className={'floating-vehicle-tile '+(state.vehicle===item.id?'is-selected':'')} data-vehicle={item.id} aria-pressed={state.vehicle===item.id} onClick={()=>chooseVehicle(item.id)} whileHover={allowed?{y:-8,rotate:i%2===0?-.8:.8}:undefined} whileTap={allowed?{scale:.98}:undefined}><span className="vehicle-tile-top"><span>0{i+1} / PRIVATE TRAVEL</span><span className="vehicle-tile-check">{state.vehicle===item.id?<Check size={16}/>:<CarFront size={17}/>}</span></span><VehicleArt kind={item.kind}/><span className="vehicle-tile-tag">{item.tag}</span><h3>{item.name}</h3><p>{item.description}</p><span className="vehicle-tile-action">{state.vehicle===item.id?'Vehicle selected':'Select this vehicle'}<ArrowRight size={17}/></span></motion.button>)}</div></section>
 {vehicle&&<aside className="booking-selection-dock" aria-label="Your package and vehicle"><div><span>{selected.name}</span><strong>{vehicle.name}</strong></div><button className="flow-button" type="button" onClick={()=>setReview(true)}>Review & book <MessageCircle size={17}/></button></aside>}
 <dialog ref={dialog} id="booking-review" className="booking-review" aria-labelledby="booking-review-title" onClose={closeReview}><button type="button" className="booking-review-close" onClick={()=>setReview(false)} aria-label="Close trip review"><X size={21}/></button><form ref={form} onSubmit={e=>{e.preventDefault();openDraft()}}><p className="flow-eyebrow">03 · YOUR TRIP, READY TO SHARE</p><h2 id="booking-review-title">Let’s arrange<br/><em>your journey.</em></h2><div className="booking-review-summary"><div><span>Package</span><strong>{selected.name}</strong></div><div><span>Vehicle</span><strong>{vehicle?.name}</strong></div></div><div className="booking-review-fields"><label>Your name <span>(optional)</span><input autoComplete="name" maxLength={100} value={state.customer.name} onChange={e=>setState(s=>({...s,customer:{...s.customer,name:e.target.value}}))}/></label><label>Travellers <span>({group?'3':'1'}–200)</span><input type="number" min={group?3:1} max={200} required value={state.customer.people} onChange={e=>setState(s=>({...s,customer:{...s.customer,people:e.target.value}}))}/></label><label>Travel date <span>(optional)</span><input type="date" min={today} value={state.customer.date} onChange={e=>setState(s=>({...s,customer:{...s.customer,date:e.target.value}}))}/></label><label>Pickup location <span>(optional)</span><input maxLength={160} value={state.customer.pickup} onChange={e=>setState(s=>({...s,customer:{...s.customer,pickup:e.target.value}}))}/></label><label className="comfort-preference">Travel preference <span>(optional)</span><select value={state.preference} onChange={e=>setState(s=>({...s,preference:e.target.value}))}><option value="">Help me choose</option>{['Budget friendly package','Deluxe package','Luxury packages','Premium packages'].map(p=><option key={p}>{p}</option>)}</select></label></div><SlideCommit key={state.vehicle} onConfirm={openDraft} disabled={!vehicle}/><p className="booking-confirmation-note">Opens a WhatsApp draft for you to review and send. Our team confirms the arrangements. No payment or reservation happens on this website.</p></form></dialog><div role="status" className="sr-only" aria-live="polite">{notice}</div></div></MotionConfig>
}
const root=document.getElementById('booking-flow-root');if(root)createRoot(root).render(<App/>);
'''
(R/'src/booking/main.tsx').write_text(source,encoding='utf-8')
print('New homepage day rail and dedicated vehicle selection flow written.')
